                                                  "explanation":  "FAUX - → Dans la couche M, la sous-couche avec le nombre quantique l le plus élevé contient… Faux. La couche est définie par le nombre quantique principal n (n = 1 → K, n = 2 → L, n = 3 → M).Pour la couche M (n = 3), les valeurs possibles du nombre quantique secondaire l sont 0, 1 et 2.La valeur la plus élevée est l = 2 (sous-couche d).Le nombre d\u0027orbitales atomiques (OA) dépend de m, qui varie de −l à +l. Pour l = 2, m ∈{−2, −1, 0, 1, 2}, soit 5 valeurs. La sous-couche contient donc 5 orbitales (et non 7)."
