                                                  "text":  "À la différence du Royaume-Uni ou de l\u0027Allemagne, la France a par exemple instauré un système de visa pour les nouveaux médicaments en 1941 - même si ce visa répond à de multiples objectifs, notamment protectionnistes*, et si les données demandées comme leur examen par l\u0027administration restent limités. [...] Au cours des années 1960 - qui sont marquées par le retrait mondial du Thalidomide en 1961, après qu\u0027il eut fait plusieurs milliers de victimes - l\u0027idée d\u0027une décision de mise sur le marché traduisant un jugement porté à la fois sur les bénéfices et les risques des produits est affirmée dans plusieurs importantes législations. [...] Puis, au cours des années 1970, l\u0027essai clinique randomisé - qui permet la mesure statistique des propriétés d\u0027un médicament en comparant ses effets à ceux d\u0027un placebo ou d\u0027un produit concurrent - s\u0027imposera comme l\u0027instrument de référence pour l\u0027évaluation de cette balance « bénéfice risque ». [...] En France, le système du visa est réformé en 1959 et en 1967 une commission d\u0027autorisation de mise sur le marché (AMM) des médicaments est instaurée.",
